f=main():i64{
let cats=mut.@();
let scraps=mut.@();
let prods=mut.@();
let totScrap=mut.0;
let totProd=mut.0;
let first=mut.1;
let go=mut.1;
lp(go>0){
let line=s.trim(io.readln());
if(s.len(line)=0){go=0}el{
if(first>0){first=0}el{
let parts=s.split(line;",");
